    explanation: 'न्यूटनच्या गतीविषयक दुसऱ्या नियमानुसार (Newton\'s Second Law of Motion), संवेग परिवर्तनाचा दर प्रयुक्त बलाशी समप्रमाणात असतो आणि संवेगाचे परिवर्तन बलाच्या दिशेने होते. या नियमाचे गणितीय समीकरण F = m * a हे आहे (येथे F = प्रयुक्त बल, m = वस्तूचे वस्तुमान, a = निर्माण होणारे त्वरण).\nया समीकरणावरून त्वरण a = F / m असे मिळते. जर वस्तूचे वस्तुमान (m) स्थिर मानले, तर निर्माण होणारे त्वरण हे प्रयुक्त बलाशी थेट समप्रमाणात असते (a ∝ F).\nआता जर वस्तूवर कार्यरत असलेले परिणामी बल दुप्पट केले (F\' = 2F), तर निर्माण होणारे नवीन त्वरण a\' = F\' / m = (2F) / m = 2 * (F / m) = 2a होईल. म्हणजेच वस्तूचे त्वरण मूळ त्वरणाच्या बरोबर \'दुप्पट होते\'. अधिक बल प्रयुक्त केल्यास वस्तूच्या वेगात होणाऱ्या बदलाचा दरही तितक्याच पटीने वाढतो. म्हणून पर्याय ४ (दुप्पट होते) हे अचूक उत्तर आहे.',
