    explanation: '३० एप्रिल १९५६ रोजी जाहीर झालेला औद्योगिक धोरण ठराव (Industrial Policy Resolution 1956) हा भारताच्या समाजवादी समाज रचनेचा आणि दुसऱ्या पंचवार्षिक योजनेचा (महालनोबिस मॉडेल) पाया ठरला. या धोरणाचे सविस्तर विश्लेषण:\nविधान (अ) अचूक : डॉ. जॉन मथाई आणि अर्थतज्ज्ञांनी या धोरणाला भारताची \'आर्थिक घटना\' किंवा \'राज्य समाजवादाचा जाहीरनामा\' असे संबोधले आहे.\nविधान (ब) अचूक : या धोरणाने भारतीय उद्योगांची तीन अनुसूचींमध्ये विभागणी केली होती:\n- अनुसूची अ (Schedule A) : १७ प्रमुख व मूलभूत उद्योग (उदा. रेल्वे, संरक्षण, लोह-पोलाद, अणुऊर्जा).\n- अनुसूची ब (Schedule B) : १२ मिश्र उद्योग (राज्य पुढाकार घेईल, खाजगी क्षेत्र पूरक राहील).\n- अनुसूची क (Schedule C) : उर्वरित सर्व ग्राहक उद्योग (खाजगी क्षेत्रासाठी खुले).\nविधान (क) पूर्णतः चूक : अनुसूची \'अ\' मधील १७ उद्योग हे केवळ खाजगी क्षेत्रासाठी नव्हे, तर \'संपूर्णतः केंद्र सरकार व सार्वजनिक क्षेत्राच्या मक्तेदारीसाठी\' राखीव ठेवण्यात आले होते.\nत्यामुळे केवळ विधाने \'अ आणि ब\' अचूक आहेत. म्हणून पर्याय २ अचूक उत्तर आहे.',
