    explanation: 'रक्तसंबंधाचे (Blood Relations) विश्लेषण करूया:\nएकनाथचे विधान : "हिच्या (सोनालीच्या) नवऱ्याचे वडील हे माझ्या आतेबहिणीचे मामा आहेत."\n१. एकनाथची आतेबहीण = एकनाथच्या आत्याची मुलगी.\n२. आतेबहिणीचे मामा = आत्याच्या भावांपैकी एक. म्हणजेच ते एकतर एकनाथचे वडील असू शकतात किंवा एकनाथचे स्वतःचे सख्खे काका/मामा असू शकतात.\n३. विधानानुसार सोनालीच्या नवऱ्याचे वडील हेच ते मामा आहेत.\nजर ते एकनाथचे स्वतःचे वडील असतील, तर सोनालीच्या नवऱ्याचे वडील = एकनाथचे वडील; म्हणजेच सोनालीचा नवरा = एकनाथ (किंवा एकनाथचा भाऊ). त्यामुळे सोनाली ही एकनाथची \'पत्नी\' किंवा \'वहिनी\' ठरते.\nजर ते एकनाथचे काका असतील, तरीही सोनाली ही एकनाथच्या चुलत भावाची पत्नी म्हणजेच \'वहिनी\' ठरते.\nत्यामुळे सोनालीचे एकनाथशी असलेले नाते \'वहिनी\' (किंवा पत्नी) हेच येते. म्हणून पर्याय ३ अचूक उत्तर आहे.',
