    correctIndex: 2,
    explanation: 'दिलेली पदावली बीजगणितीय नित्यसमीकरणाच्या (Algebraic Identity) स्वरूपात आहे:\nपदावली : (२.४)² - २ × (२.४) × (४.५) + (४.५)²\nसमजा a = २.४ आणि b = ४.५ मानू.\nही मांडणी a² - 2ab + b² या स्वरूपात आहे.\nआपल्याला माहीत आहे की : a² - 2ab + b² = (a - b)² = (b - a)².\nकिमती ठेवूया:\n= (२.४ - ४.५)²\n= (- २.१)²\nकोणत्याही ऋण संख्येचा वर्ग नेहमी धन संख्या असतो:\n(- २.१)² = (- २.१) × (- २.१) = + ४.४१.\nकिंवा (४.५ - २.४)² = (२.१)² = ४.४१.\nत्यामुळे पदावलीचे अचूक मूल्य ४.४१ हे येते. म्हणून पर्याय ३ (४.४१) अचूक उत्तर आहे.',
