    explanation: 'वयाच्या गणिताची समीकरण पद्धतीद्वारे मांडणी करूया:\nसमजा, तुषारचे आजचे वय = x वर्षे मानू.\nअट १ : वडिलांचे आजचे वय तुषारच्या वयाच्या ४ पट आहे,\nम्हणून वडिलांचे आजचे वय = 4x वर्षे.\nअट २ : ५ वर्षांपूर्वीची स्थिती:\n५ वर्षांपूर्वी तुषारचे वय = (x - ५) वर्षे.\n५ वर्षांपूर्वी वडिलांचे वय = (4x - ५) वर्षे.\nगणितातील अटीनुसार ५ वर्षांपूर्वी वडिलांचे वय मुलाच्या वयाच्या ७ पट होते:\n4x - ५ = ७ × (x - ५)\n4x - ५ = 7x - ३५\nसंख्या एका बाजूला आणि चल एका बाजूला करू:\n३५ - ५ = 7x - 4x\n३० = 3x\nx = ३० / ३ = १० वर्षे (तुषारचे आजचे वय).\nआता वडिलांचे आजचे वय काढू:\nवडिलांचे आजचे वय = 4x = ४ × १० = ४० वर्षे.\nपडताळणी : ५ वर्षांपूर्वी वडील ४० - ५ = ३५ वर्षांचे होते आणि मुलगा १० - ५ = ५ वर्षांचा होता. ३५ हे ५ च्या बरोबर ७ पट (५ × ७ = ३५) आहे, त्यामुळे समीकरण अचूक जुळते. म्हणून पर्याय ३ (४० वर्षे) अचूक उत्तर आहे.',
