    explanation: 'प्लॅटफॉर्मवर उभ्या व्यक्तीला पार करण्यासाठी लागणारा वेळ = गाडीची लांबी / गाडीचा वेग (मी/सेकंद).\nवेगाचे रूपांतर किमी/तास वरून मीटर/सेकंद मध्ये करण्यासाठी ५/१८ ने गुणूया:\nगाडी १ :\nलांबी = ३१५ मीटर.\nवेग = ४२ किमी/तास = ४२ × (५/१८) = २१० / १८ = ३५ / ३ मी/से.\nवेळ (T1) = ३१५ / (३५/३) = (३१५ × ३) / ३५ = ९ × ३ = २७ सेकंद.\nगाडी २ :\nलांबी = २१० मीटर.\nवेग = ५४ किमी/तास = ५४ × (५/१८) = ३ × ५ = १५ मी/से.\nवेळ (T2) = २१० / १५ = १४ सेकंद.\nलागणाऱ्या वेळेतील फरक:\nफरक = T1 - T2 = २७ सेकंद - १४ सेकंद = १३ सेकंद.\nत्यामुळे दोन्ही गाड्यांना त्या व्यक्तीला पार करण्यासाठी लागणाऱ्या वेळेमध्ये १३ सेकंदांचा फरक असेल. म्हणून पर्याय ४ (१३ सेकंद) हे अचूक उत्तर आहे.',
