    explanation: 'हे गणित मिश्रणाच्या नियमाने (Rule of Alligation) अत्यंत सहजपणे सोडवता येते:\nस्वस्त तांदळाची किंमत (C) = ₹६० प्रति किलो.\nमहाग तांदळाची किंमत (D) = ₹८५ प्रति किलो.\nमिश्रणाची सरासरी किंमत (M) = ₹७० प्रति किलो.\nमिश्रणाच्या नियमानुसार गुणोत्तर:\n(स्वस्त तांदळाचे प्रमाण) / (महाग तांदळाचे प्रमाण) = (D - M) / (M - C)\n= (८५ - ७०) / (७० - ६०)\n= १५ / १०.\nअंश आणि छेदाला ५ ने भागूया:\n= (१५ ÷ ५) / (१० ÷ ५)\n= ३ / २.\nम्हणजेच गुणोत्तर ३ : २ असे येते.\nपडताळणी : समजा ३ किलो ६० रुपयांचे तांदूळ (३ × ६० = १८० रु.) आणि २ किलो ८५ रुपयांचे तांदूळ (२ × ८५ = १७० रु.) घेतले. एकूण वजन = ५ किलो आणि एकूण किंमत = १८० + १७० = ३५० रु. प्रति किलो दर = ३५० / ५ = ₹७० बरोबर येतो. म्हणून पर्याय २ (३ : २) हे अचूक उत्तर आहे.',
