    explanation: 'वयाच्या गुणोत्तराचे समीकरण मांडूया:\nराम आणि शाम यांच्या आजच्या वयाचे गुणोत्तर = ४ : ५ आहे.\nसमजा समान पट x मानू.\nम्हणून रामचे आजचे वय = 4x वर्षे, आणि शामचे आजचे वय = 5x वर्षे.\n६ वर्षांनंतरची स्थिती:\n६ वर्षांनंतर रामचे वय = (4x + ६) वर्षे.\n६ वर्षांनंतर शामचे वय = (5x + ६) वर्षे.\nगणितातील अटीनुसार ६ वर्षांनंतर गुणोत्तर ५ : ६ होते:\n(4x + ६) / (5x + ६) = ५ / ६\nतिरकस गुणाकार करूया:\n६ × (4x + ६) = ५ × (5x + ६)\n24x + ३६ = 25x + ३०\nचल आणि संख्या एका बाजूला करू:\n३६ - ३० = 25x - 24x\nx = ६.\nआता रामचे आजचे वय काढू:\nरामचे आजचे वय = 4x = ४ × ६ = २४ वर्षे.\n(शामचे आजचे वय ५ × ६ = ३० वर्षे होईल).\nपडताळणी : ६ वर्षांनंतर राम २४ + ६ = ३० चा होईल आणि शाम ३० + ६ = ३६ चा होईल. गुणोत्तर ३०/३६ = ५/६ बरोबर जुळते. म्हणून पर्याय १ (२४ वर्षे) अचूक उत्तर आहे.',
