    correctIndex: 2,
    explanation: 'चक्रवाढ व्याजाची (Compound Interest) गणना करूया:\nमुद्दल (P) = ₹१०,०००\nव्याजाचा दर (R) = १०% दरसाल दरकवडा\nमुदत (N) = २ वर्षे.\nपद्धत १ (रास सूत्र) :\nरास (A) = P × (१ + R/१००)^N\nA = १०,००० × (१ + १०/१००)²\nA = १०,००० × (११/१०) × (११/१०)\nA = १०,००० × (१२१ / १००)\nA = १०० × १२१ = ₹१२,१०० (एकूण रास).\nचक्रवाढ व्याज (CI) = रास (A) - मुद्दल (P)\n= १२,१०० - १०,०००\n= ₹२,१००.\nपद्धत २ (टक्केवारी पद्धत) :\nपहिल्या वर्षाचे व्याज = १०,००० चे १०% = ₹१,०००.\nदुसऱ्या वर्षाचे व्याज = १०,००० चे १०% (१०००) + मागील व्याजावर १०% (१००० चे १०% = १००) = ₹१,१००.\nएकूण चक्रवाढ व्याज = १००० + ११०० = ₹२,१००.\nत्यामुळे २ वर्षांचे चक्रवाढ व्याज ₹२,१०० होईल. म्हणून पर्याय ३ अचूक उत्तर आहे.',
